"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta, timezone

from logkeep import streams
from logkeep.errors import DataError

_NUM = re.compile(r"[0-9]+\Z")
_SIZE = re.compile(r"([0-9]+)([KkMmGg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_UNITS = {"": 1, "k": 1024, "m": 1024 ** 2, "g": 1024 ** 3}
_MINUTES = {"m": 1, "h": 60, "d": 1440}


class Invalid(ValueError):
    pass


def _off_or(parse):
    def inner(v):
        return None if v == "off" else parse(v)
    return inner


def _size(v):
    m = _SIZE.match(v)
    if not m:
        raise Invalid(v)
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _duration(v):
    m = _DURATION.match(v)
    if not m:
        raise Invalid(v)
    return timedelta(minutes=int(m.group(1)) * _MINUTES[m.group(2)])


def _naming(v):
    if v not in ("numbered", "dated"):
        raise Invalid(v)
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise Invalid(v)
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(-delta if m.group(1) == "-" else delta)


def _whole(minimum):
    def inner(v):
        if not _NUM.match(v) or int(v) < minimum:
            raise Invalid(v)
        return int(v)
    return inner


# key: (parser, built-in value)
SETTINGS = {
    "max_size": (_off_or(_size), None),
    "max_age": (_off_or(_duration), None),
    "naming": (_naming, "numbered"),
    "offset": (_offset, timezone.utc),
    "compress_after": (_whole(0), 1),
    "keep": (_whole(1), 5),
    "keep_days": (_off_or(_whole(1)), None),
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections

    def stream_names(self) -> set:
        return set(self.sections)

    def get(self, name: str) -> dict:
        own = self.sections.get(name, {})
        out = {}
        for key, (_, builtin) in SETTINGS.items():
            if key in own:
                out[key] = own[key]
            elif key in self.defaults:
                out[key] = self.defaults[key]
            else:
                out[key] = builtin
        return out


def load(path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    defaults, sections = {}, {}
    seen_defaults = False
    current = None
    try:
        for raw in text.splitlines():
            line = raw.strip()
            if not line or line[0] in "#;":
                continue
            if line[0] == "[":
                if line[-1] != "]":
                    raise Invalid(line)
                title = line[1:-1]
                if title == "defaults":
                    if seen_defaults:
                        raise Invalid(line)
                    seen_defaults = True
                    current = defaults
                elif title.startswith("stream ") and streams.valid(title[7:]):
                    name = title[7:]
                    if name in sections:
                        raise Invalid(line)
                    current = sections[name] = {}
                else:
                    raise Invalid(line)
                continue
            if current is None or "=" not in line:
                raise Invalid(line)
            key, _, value = line.partition("=")
            key, value = key.strip(), value.strip()
            if key not in SETTINGS or key in current:
                raise Invalid(line)
            current[key] = SETTINGS[key][0](value)
    except (Invalid, ValueError):
        raise DataError("policy", f"{path.name}: invalid policy") from None
    return Policy(defaults, sections)

