import gzip
import os
import re
from datetime import date, datetime, timedelta

from logkeep import dates, policy as policy_mod, state, streams
from logkeep.errors import DataError, Refused

_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")


class Archive:
    def __init__(self, key, gz, old):
        self.key = key      # numbered: N; dated: (date, K)
        self.gz = gz
        self.old = old      # file name before the run, None for the new archive
        self.time = None    # time text in state.json
        self.new = old is None
        self.final = None
        self.compressed = False


def _whole(v):
    return isinstance(v, int) and not isinstance(v, bool) and v >= 0


def _check_state(doc, existing):
    for name, entry in doc["streams"].items():
        if name not in existing:
            continue
        try:
            if "opened" in entry:
                dates.parse_state(entry["opened"])
            if "archives" in entry:
                arch = entry["archives"]
                if not isinstance(arch, dict):
                    raise ValueError("archives")
                for v in arch.values():
                    dates.parse_state(v)
            if "rotations" in entry and not _whole(entry["rotations"]):
                raise ValueError("rotations")
        except (ValueError, TypeError, OverflowError):
            raise DataError("state", f"state.json: bad entry for {name}") from None


def _find_archives(ctx, name, naming):
    d = streams.logs_dir(ctx.data)
    found = {}
    if not d.is_dir():
        return []
    prefix = f"{name}.log."
    for p in d.iterdir():
        if not p.name.startswith(prefix) or not p.is_file():
            continue
        rest = p.name[len(prefix):]
        if naming == "numbered":
            m = _NUMBERED.match(rest)
            if not m:
                continue
            key, gz = int(m.group(1)), bool(m.group(2))
        else:
            m = _DATED.match(rest)
            if not m:
                continue
            try:
                day = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            key, gz = (day, int(m.group(2)) if m.group(2) else 1), bool(m.group(3))
        if key in found:
            raise DataError("archives", f"{name}: two archives in the same place")
        found[key] = Archive(key, gz, p.name)
    arch = list(found.values())
    arch.sort(key=lambda a: a.key, reverse=(naming == "dated"))
    return arch


def _first_line_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
        token = line.rstrip(b"\r\n").split(b" ", 1)[0].decode("utf-8")
        return dates.parse_iso(token)
    except (OSError, ValueError, UnicodeDecodeError):
        return None


def _stem(name, key, naming):
    if naming == "numbered":
        return f"{name}.log.{key}"
    day, k = key
    return f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")


def _plan(ctx, name, pol, entry, force):
    naming = pol["naming"]
    archives = _find_archives(ctx, name, naming)
    arch_times = entry.get("archives", {})
    for a in archives:
        a.time = arch_times.get(a.old)

    log = streams.log_path(ctx.data, name)
    why = None
    size = None
    if not log.is_file():
        what = "no log"
    else:
        size = log.stat().st_size
        if size == 0:
            what = "empty"
        elif force:
            what, why = "rotate (forced)", True
        else:
            what = "not due"
            if pol["max_size"] is not None and size >= pol["max_size"]:
                what, why = "rotate (size)", True
            elif pol["max_age"] is not None:
                if "opened" in entry:
                    opened = dates.parse_state(entry["opened"])
                else:
                    opened = _first_line_time(log)
                if opened is not None and ctx.now - opened >= pol["max_age"]:
                    what, why = "rotate (age)", True
    rotated = bool(why)

    if rotated:
        if naming == "numbered":
            key = 0
        else:
            day = ctx.now.astimezone(pol["offset"]).date()
            ks = [a.key[1] for a in archives if a.key[0] == day]
            key = (day, max(ks) + 1 if ks else 1)
        new = Archive(key, False, None)
        new.time = dates.stamp(ctx.now)
        archives.append(new)
        archives.sort(key=lambda a: a.key, reverse=(naming == "dated"))

    keep, keep_days = pol["keep"], pol["keep_days"]
    remaining, removed = [], []
    for pos, a in enumerate(archives, 1):
        drop = pos > keep
        if not drop and keep_days is not None and a.time is not None:
            if ctx.now - dates.parse_state(a.time) >= timedelta(days=keep_days):
                drop = True
        (removed if drop else remaining).append(a)

    lines = [f"{name}: {what}"]
    ncompressed = 0
    for i, a in enumerate(remaining, 1):
        if i > pol["compress_after"] and not a.gz:
            a.compressed = True
        gz = a.gz or a.compressed
        stem = f"{name}.log.{i}" if naming == "numbered" else _stem(name, a.key, naming)
        a.final = stem + (".gz" if gz else "")
        if a.compressed:
            ncompressed += 1
        if a.new:
            lines.append(f"  new {a.final}")
        elif a.final != a.old:
            lines.append(f"  {a.final} <- {a.old}")
        else:
            lines.append(f"  {a.final}")
    for a in removed:
        lines.append(f"  remove {a.old if a.old else _stem(name, a.key, naming)}")

    new_entry = {}
    if rotated:
        new_entry["opened"] = dates.stamp(ctx.now)
    elif "opened" in entry:
        new_entry["opened"] = entry["opened"]
    new_entry["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
    new_entry["archives"] = {a.final: a.time for a in remaining if a.time is not None}
    return {"name": name, "lines": lines, "remaining": remaining, "removed": removed, "rotated": rotated,
            "ncompressed": ncompressed, "entry": new_entry, "log": log}


def _apply(ctx, plan):
    d = streams.logs_dir(ctx.data)

    def tmp(a):
        return d / f".{a.final}.logkeep-tmp"

    staged = []
    if plan["rotated"]:
        data = plan["log"].read_bytes()
    for a in plan["remaining"]:
        if a.new:
            raw = gzip.compress(data, mtime=0) if a.compressed else data
            tmp(a).write_bytes(raw)
            staged.append(a)
        elif a.compressed:
            raw = gzip.compress((d / a.old).read_bytes(), mtime=0)
            tmp(a).write_bytes(raw)
            staged.append(a)
        elif a.final != a.old:
            os.replace(d / a.old, tmp(a))
            staged.append(a)
    for a in plan["removed"]:
        if not a.new:
            (d / a.old).unlink()
    for a in plan["remaining"]:
        if a.compressed and not a.new:
            (d / a.old).unlink()
    if plan["rotated"]:
        with plan["log"].open("wb"):
            pass
    for a in staged:
        os.replace(tmp(a), d / a.final)


def run(ctx, names, dry_run=False, force=False):
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | pol.stream_names()
    _check_state(doc, existing)
    wanted = sorted(set(names)) if names else sorted(existing)
    for n in wanted:
        if n not in existing:
            raise Refused("unknown-stream", f"no stream {n}")

    plans = []
    for n in wanted:
        plans.append(_plan(ctx, n, pol.get(n), doc["streams"].get(n, {}), force))

    out = []
    for p in plans:
        out.extend(p["lines"])
    r = sum(1 for p in plans if p["rotated"])
    x = sum(len(p["removed"]) for p in plans)
    c = sum(p["ncompressed"] for p in plans)
    out.append(f"{r} rotated, {x} removed, {c} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    for p in plans:
        _apply(ctx, p)
        doc["streams"][p["name"]] = p["entry"]
    ctx.state_path.parent.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, doc)
    return out

